//2d recursive orbits, but on collision the circles switch to orbiting the one they collide with, so they create new configurations
//somehow it looks very fake, like cartoon physics? but also- cool trails, man


let circles;

let lastTime = Date.now();

let centerX;
let centerY;

let paused = false;
let speedMultiplier = 1;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(100);
	centerX = width / 2;
	centerY = height / 2;
	const circle1 = new Circle(30, '#ff6b6b', 0, 0, null);
	const circle2 = new Circle(25, '#4ecdc4', 170, 0.5, circle1, 0);
	const circle3 = new Circle(20, '#ffe66d', 80, 1.2, circle2, 0);
	const circle4 = new Circle(15, '#a8e6cf', 60, 1.8, circle3, 0);
	const circle5 = new Circle(12, '#ff9ff3', 50, 2.5, circle4, 0);
	const circle6 = new Circle(10, '#feca57', 40, -3.2, circle5, 0);
	const circle7 = new Circle(8, '#48dbfb', 35, 4.0, circle6, 0);
	const circle8 = new Circle(7, '#ff6348', 30, 4.8, circle7, 0);
	const circle9 = new Circle(6, '#1dd1a1', 25, 5.6, circle8, 0);

	circles = [circle1, circle2, circle3, circle4, circle5, circle6, circle7, circle8, circle9];


}

function draw() {
	background(0);
	const currentTime = Date.now();
	const dt = (currentTime - lastTime) / 1000;
	lastTime = currentTime;

	for (let i = 0; i < circles.length; i++) {
		let c = circles[i];
		c.update(dt);
	}
	checkCollisions();
	for (let i = 0; i < circles.length; i++) {
		let c = circles[i];
		c.draw();
	}
}

function reset() {
	circle1.angle = 0;
	circle2.angle = 0;
	circle2.parent = circle1;
	circle2.orbitRadius = 120;
	circle3.angle = 0;
	circle3.parent = circle2;
	circle3.orbitRadius = 80;
	circle4.angle = 0;
	circle4.parent = circle3;
	circle4.orbitRadius = 60;
	circle5.angle = 0;
	circle5.parent = circle4;
	circle5.orbitRadius = 50;
	circle6.angle = 0;
	circle6.parent = circle5;
	circle6.orbitRadius = 40;
	circle7.angle = 0;
	circle7.parent = circle6;
	circle7.orbitRadius = 35;
	circle8.angle = 0;
	circle8.parent = circle7;
	circle8.orbitRadius = 30;
	circle9.angle = 0;
	circle9.parent = circle8;
	circle9.orbitRadius = 25;
	circles.forEach(circle => circle.trail = []);
	lastTime = Date.now();
}

function checkCollisions() {
	// Check each circle against all potential parents

	for (let i = 1; i < circles.length; i++) {
		const current = circles[i];

		// Check collision with all circles before it (potential parents)
		for (let j = 0; j < i; j++) {
			const potential = circles[j];
			if (current.isColliding(potential) && current.parent !== potential) {
				current.switchOrbit(potential);
				break; // Only switch to one parent at a time
			}
		}
	}
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

